  const conBoton = async (btn, fn) => { btn.disabled = true; const f = btn.closest('form, .card'); f?.querySelector('.err')?.remove(); try { await fn(); } catch (e) { toast('⚠️ ' + e.message); if (f && f.isConnected) { const p = document.createElement('p'); p.className = 'err'; p.textContent = '⚠️ ' + e.message; p.style.cssText = 'background:#fee2e2;color:#991b1b;border-radius:10px;padding:10px 12px;font-weight:700;margin:10px 0 0'; (btn.closest('.fila') || btn).after(p); p.scrollIntoView({ block: 'nearest' }); } } finally { btn.disabled = false; } }; // el error se ve en rojo dentro del formulario

